window.AUTH=window.AUTH||{};window.AUTH["18-1023"]={"d":"18-1023","id":"2019/18-1023","n":"Maine Community Health Options v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Maine Community Health Options","date":"2019-08-30","url":"https://www.supremecourt.gov/DocketPDF/18/18-1023/114323/20190830144530676_18-1023ts.pdf","side":"pet","n":61},{"k":"petitioner","label":"Brief of petitioner Land of Lincoln Mutual Health Insurance Company","date":"2019-08-30","url":"https://www.supremecourt.gov/DocketPDF/18/18-1023/114267/20190830124053503_18-1023%20ts%20Land%20of%20Lincoln.pdf","side":"pet","n":72},{"k":"petitioner","label":"Brief of petitioners Moda Health Plan, Inc., and Blue Cross and Blue Shield of North Carolina","date":"2019-08-30","url":"https://www.supremecourt.gov/DocketPDF/18/18-1023/114320/20190830143120987_18-1028%20Brief%20for%20Petitioners.pdf","side":"pet","n":56},{"k":"respondent","label":"Brief of respondent United States","date":"2019-10-21","url":"https://www.supremecourt.gov/DocketPDF/18/18-1023/119724/20191021193212221_18-1023bsUnitedStates.pdf","side":"res","n":91},{"k":"reply","label":"Reply of petitioner Maine Community Health Options","date":"2019-11-19","url":"https://www.supremecourt.gov/DocketPDF/18/18-1023/122922/20191119141716260_18-1023rb.pdf","side":"pet","n":30},{"k":"reply","label":"Reply of petitioner Moda Health Plan, Inc.","date":"2019-11-20","url":"https://www.supremecourt.gov/DocketPDF/18/18-1023/123086/20191120125558779_2019-11-20%20Moda%20Merits%20Reply%20FINAL.pdf","side":"pet","n":29},{"k":"reply","label":"Reply of petitioner Land of Lincoln Mutual Health Insurance Company","date":"2019-11-20","url":"https://www.supremecourt.gov/DocketPDF/18/18-1023/123168/20191120163457697_18-1038rb.pdf","side":"pet","n":64}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/590US1PP_web.pdf#page=312","tr":true,"items":[{"t":"case","label":"Agwiak v. United States","cite":"347 F.3d 1375","y":2003,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/347/1375/","by":{"0":"25"}},{"t":"case","label":"Alpine PCS, Inc. v. United States","cite":"878 F.3d 1086","y":2018,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/878/1086/","by":{"0":"26","4":"20"}},{"t":"case","label":"Bowen v. Massachusetts","cite":"487 U.S. 879","y":1988,"id":"1987/87-712","sc":1,"by":{"0":"24, 25, 26","3":"31, 32, 33","4":"19, 20, 21, 22","5":"20","6":"20, 21"},"q":[{"src":"brief","b":0,"text":"[A] statute commanding the payment of a specified amount of money by the United States impliedly authorizes (absent other indication) a claim for damages in the defaulted amount.","cite":"487 U.S. 879, 923-24"},{"src":"brief","b":3,"text":"provide[d] that [HHS] ‘shall pay’ certain amounts for appropriate Medicaid services.","cite":"487 U.S. at 900"},{"src":"brief","b":4,"text":"It seems likely that while Congress intended ‘shall pay’ language in statutes such as the Back Pay Act to be self-enforcing—i.e., to create both a right and a remedy—it intended similar language in § 1396b(a) of the Medicaid Act to provide merely a right, knowing that the APA provided for review of this sort of agency action.","cite":"487 U.S. at 906 n.42"},{"src":"brief","b":5,"text":"a statute commanding the payment of a specified amount of money by the United States impliedly authorizes (absent other indication) a claim for damages in the defaulted amount.","cite":"487 U.S. 879, 923"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"to create both a right and a remedy","cite":"487 U. S., at 906, n. 42"}]},{"t":"case","label":"Branch v. Smith","cite":"538 U.S. 254","y":2003,"id":"2002/01-1437","sc":1,"by":{"0":"43","1":"22"}},{"t":"case","label":"Collins v. United States","cite":"15 Ct. Cl. 22","y":1879,"url":"https://www.courtlistener.com/c/Ct.%20Cl./15/22/","by":{"0":"31, 32"}},{"t":"case","label":"Fernandez-Vargas v. Gonzales","cite":"548 U.S. 30","y":2006,"id":"2005/04-1376","sc":1,"by":{"0":"45","3":"51, 52"},"q":[{"src":"brief","b":3,"text":"Statutes are disfavored as retroactive when their application ‘would impair rights a party possessed when he acted, increase a party’s liability for past conduct, or impose new duties with respect to transactions already completed.’","cite":"548 U.S. 30, 37"}]},{"t":"case","label":"Ferris v. United States","cite":"27 Ct. Cl. 542","y":1892,"url":"https://www.courtlistener.com/c/Ct.%20Cl./27/542/","by":{"0":"33, 36, 54","1":"27","2":"30","3":"33","4":"6, 7","5":"13"},"q":[{"src":"brief","b":0,"text":"insufficiency does not pay the Government’s debts, nor cancel its obligations, nor defeat the rights of other parties.","cite":"27 Ct. Cl. 542, 546"},{"src":"brief","b":0,"text":"defeat the rights of other parties.","cite":"27 Ct. Cl. at 546"}]},{"t":"case","label":"Fisher v. United States","cite":"402 F.3d 1167","y":2005,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/402/1167/","by":{"0":"26","3":"33"}},{"t":"case","label":"Gibney v. United States","cite":"114 Ct. Cl. 38","y":1949,"url":"https://www.courtlistener.com/c/Ct.%20Cl./114/38/","by":{"0":"31"}},{"t":"case","label":"Graham v. United States","cite":"1 Ct. Cl. 380","y":1865,"url":"https://www.courtlistener.com/c/Ct.%20Cl./1/380/","by":{"0":"37"}},{"t":"case","label":"Greenlee Cty., Ariz. v. United States","cite":"487 F.3d 871","y":2007,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/487/871/","by":{"0":"25, 28","3":"33","4":"12, 19","5":"15","6":"5, 13"},"q":[{"src":"brief","b":0,"text":"use of the word ‘shall’ generally makes a statute money-mandating.","cite":"487 F.3d 871, 876-77"}]},{"t":"case","label":"Highland Falls-Fort Montgomery Cent. Sch. Dist. v. United States","cite":"48 F.3d 1166","y":2018,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/48/1166/","by":{"0":"28","3":"26, 27, 39","4":"12, 17, 18","5":"15, 16","6":"13, 14"}},{"t":"case","label":"J.E.M. Ag Supply, Inc. v. Pioneer Hi-Bred Int’l, Inc.","cite":"534 U.S. 124","y":2001,"id":"2001/99-1996","sc":1,"by":{"0":"43","1":"22"}},{"t":"case","label":"Landgraf. v. USI Film Prods.","cite":"511 U.S. 244","y":1994,"id":"1993/92-757","sc":1,"by":{"0":"41, 45, 47","1":"43","2":"34, 47"},"q":[{"src":"brief","b":0,"text":"and determined that it is an acceptable price to pay for the countervailing benefits.","cite":"511 U.S. 244, 272-73"},{"src":"brief","b":1,"text":"impair rights a party possessed when he acted.","cite":"511 U.S. 244, 280"},{"src":"brief","b":2,"text":"Elementary considerations of fairness dictate that individuals should have an opportunity to know what the law is and to conform their conduct accordingly[.]","cite":"511 U.S. 244, 265"},{"src":"brief","b":2,"text":"clear congressional intent favoring such a result,","cite":"511 U.S. at 280"}]},{"t":"case","label":"Miller v. United States","cite":"86 Ct. Cl. 609","y":1938,"url":"https://www.courtlistener.com/c/Ct.%20Cl./86/609/","by":{"0":"37"}},{"t":"case","label":"Moda Health Plan, Inc. v. United States","cite":"892 F.3d 1311","y":2018,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/892/1311/","by":{"0":"passim","1":"1","4":"4"},"q":[{"src":"brief","b":0,"text":"dampened ACA enrollment in states implementing the policy, especially by healthier individuals who elected to maintain their lower level of coverage, leaving insurers participating in the exchanges to bear greater risk than they accounted for in setting premiums.","cite":"892 F.3d at 1317"},{"src":"brief","b":0,"text":"bare failure to appropriate funds to meet a statutory obligation,","cite":"892 F.3d at 1323"}]},{"t":"case","label":"Moda Health Plan, Inc. v. United States","cite":"908 F.3d 738","y":2018,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/908/738/","by":{"0":"passim","1":"1"}},{"t":"case","label":"Molina Healthcare of Cal. Inc. v. United States","cite":"133 Fed. Cl. 14","y":2017,"url":"https://www.courtlistener.com/c/Fed.%20Cl./133/14/","by":{"0":"46","3":"24","5":"11"}},{"t":"case","label":"Morton v. Mancari","cite":"417 U.S. 535","y":1974,"id":"1973/73-362","sc":1,"by":{"0":"39, 43","2":"28","3":"25"},"q":[{"src":"brief","b":0,"text":"[W]hen two statutes are capable of coexistence, it is the duty of the courts, absent a clearly expressed congressional intention to the contrary, to regard each as effective.","cite":"417 U.S. 535, 551"},{"src":"brief","b":0,"text":"when two statutes are capable of coexistence, it is the duty of the courts, absent a clearly expressed congressional intention to the contrary, to regard each as effective.","cite":"417 U.S. at 551"},{"src":"brief","b":3,"text":"[W]hen two statutes are capable of co-existence, it is the duty of the courts, absent a clearly expressed congressional intention to the contrary, to regard each as effective,","cite":"417 U.S. 535, 551"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"repeals by implication are not favored,","cite":"417 U. S. 535, 549"}]},{"t":"case","label":"N.Y. Airways, Inc. v. United States","cite":"369 F.2d 743","y":1966,"court":"Ct. Cl.","url":"https://www.courtlistener.com/c/F.2d/369/743/","by":{"0":"36","1":"28, 51","3":"33","6":"13, 16, 24"},"q":[{"src":"brief","b":1,"text":"Thus the proposal was converted into a contract, as to which the company by performing its part became entitled to performance by the government.","cite":"369 F.2d at 751"}]},{"t":"case","label":"Parsons v. United States","cite":"15 Ct. Cl. 246","y":1879,"url":"https://www.courtlistener.com/c/Ct.%20Cl./15/246/","by":{"0":"37"}},{"t":"case","label":"Posadas v. Nat’l City Bank of N.Y.","cite":"296 U.S. 497","y":1936,"id":"scdb/1935-071","sc":1,"by":{"0":"38, 41, 43","2":"22"},"q":[{"src":"brief","b":2,"text":"cardinal rule … that repeals by implication are not favored,","cite":"296 U.S. 497, 503"}]},{"t":"case","label":"Prairie Cty., Mont. v. United States","cite":"113 Fed. Cl. 194","y":2013,"url":"https://www.courtlistener.com/c/Fed.%20Cl./113/194/","by":{"0":"28","4":"12"}},{"t":"case","label":"Salazar v. Ramah Navajo Chapter","cite":"567 U.S. 182","y":2012,"id":"2011/11-551","sc":1,"by":{"0":"passim","1":"27, 28, 46, 48","2":"24, 30, 35, 57","3":"36, 37, 38, 39, 40","4":"6, 9, 12","5":"passim","6":"passim"},"q":[{"src":"brief","b":0,"text":"subject to the availability of appropriations,","cite":"567 U.S. 182, 188-89"},{"src":"brief","b":0,"text":"insufficiency does not pay the Government’s debts, nor cancel its obligations, nor defeat the rights of other parties.","cite":"567 U.S. at 197"},{"src":"brief","b":1,"text":"pay the Government’s debts, nor cancel its obligations.","cite":"567 U.S. 182, 197"},{"src":"brief","b":1,"text":"[i]f the Government could be trusted to fulfill its promise to pay only when more pressing fiscal needs did not arise, would-be contractors would bargain warily — if at all — and only at a premium large enough to account for the risk of nonpayment.","cite":"567 U.S. at 191"},{"src":"brief","b":2,"text":"would-be contractors would bargain warily—if at all—and only at a premium large enough to account for the risk of nonpayment.","cite":"567 U.S. 182, 191-92"},{"src":"brief","b":2,"text":"pay the Government’s debts, nor cancel its obligations.","cite":"567 U.S. at 197"},{"src":"brief","b":3,"text":"the provision of funds under ISDA is subject to the availability of appropriations.","cite":"567 U.S. at 186"},{"src":"brief","b":3,"text":"could cause the Secretary to violate the Anti-Deficiency Act,","cite":"567 U.S. at 197"}]},{"t":"case","label":"Slattery v. United States","cite":"635 F.3d 1298","y":2011,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/635/1298/","by":{"0":"30","3":"33","4":"7","5":"15"}},{"t":"case","label":"Strong v. United States","cite":"60 Ct. Cl. 627","y":1925,"url":"https://www.courtlistener.com/c/Ct.%20Cl./60/627/","by":{"0":"37","4":"6"}},{"t":"case","label":"Tenn. Valley Auth. v. Hill","cite":"437 U.S. 153","y":1978,"id":"1977/76-1701","sc":1,"by":{"0":"42","1":"22, 36","2":"passim","3":"51","5":"3"},"q":[{"src":"brief","b":1,"text":"[t]he doctrine disfavoring repeals by implication . . . applies with even greater force when the claimed repeal rests solely on an Appropriations Act.","cite":"437 U.S. 153, 190"},{"src":"brief","b":2,"text":"when … the subsequent legislation is an appropriations measure,","cite":"437 U.S. 153, 190"},{"src":"brief","b":2,"text":"applies with even greater force when the claimed repeal rests solely on an Appropriations Act.","cite":"437 U.S. at 190"}]},{"t":"case","label":"United States Fid. & Guar. Co. v. United States","cite":"209 U.S. 306","y":1908,"id":"scdb/1907-146","sc":1,"by":{"0":"45","2":"47"}},{"t":"case","label":"United States v. Bormes","cite":"568 U.S. 6","y":2012,"id":"2012/11-192","sc":1,"by":{"0":"26","3":"19, 20","4":"20, 22"},"q":[{"src":"brief","b":3,"text":"do not themselves ‘creat[e] substantive rights. ’","cite":"568 U.S. 6, 10"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"failure to perform an obligation . . . creat[e] a right to monetary relief","cite":"568 U. S. 6, 16"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"suppl[y] the missing ingredient for an action against the United States for the breach of monetary obligations not otherwise judicially enforceable.","cite":"568 U. S., at 12"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"a law assertedly imposing monetary liability on the United States contains its own judicial remedies.","cite":"568 U. S., at 12"}]},{"t":"case","label":"United States v. Dickerson","cite":"310 U.S. 554","y":1940,"id":"scdb/1939-059","sc":1,"by":{"0":"50, 51","1":"passim","2":"passim","3":"44, 47","5":"4, 15","6":"22"},"q":[{"src":"argument","who":"Mr. Clement","text":"But the other way to look at that is, if you look at cases like Langston, like Dickerson, like Will, in the original statute that provided for a salary or provided for a payment, none of those original statutes had language that talked specifically about budget authority."},{"src":"argument","who":"Mr. Clement","text":"The cases like Dickerson and Will, they were talking about prospective obligations for the next year. When this Court has confronted cases where the government was saying that it didn't have to pay for past obligations, cases like the Twenty Per Cent Cases and the Larionoff case that are cited in the reply brief of Land of Lincoln, the government never won those cases."},{"src":"argument","who":"Mr. Clement","text":"It doesn't even have the \"this or any other act\" language that was at issue in Will or Dickerson. And to be clear, that's not because Congress forgot how to use that phrase."}]},{"t":"case","label":"United States v. Hansen","cite":"772 F.2d 940","y":1985,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/772/940/","by":{"0":"42"},"q":[{"src":"brief","b":0,"text":"is important, primarily to facilitate not the task of judging but the task of legislating. It is one of the fundamental ground rules under which laws are framed.","cite":"772 F.2d 940, 944"}]},{"t":"case","label":"United States v. Langston","cite":"118 U.S. 389","y":1886,"id":"scdb/1885-272","sc":1,"by":{"0":"30, 39, 40, 49","1":"passim","2":"passim","3":"27, 30, 31, 49, 50","4":"4, 16, 17","5":"3, 10, 14","6":"passim"},"q":[{"src":"brief","b":2,"text":"words that expressly, or by clear implication, modif[y] or repeal[] the previous law.","cite":"118 U.S. 389, 394"},{"src":"brief","b":2,"text":"words that expressly, or by clear implication, modified or repealed the previous law.","cite":"118 U.S. at 394"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"expressly or by clear implication modif[ying]","cite":"118 U. S., at 394"},{"src":"argument","who":"Mr. Clement","text":"But the other way to look at that is, if you look at cases like Langston, like Dickerson, like Will, in the original statute that provided for a salary or provided for a payment, none of those original statutes had language that talked specifically about budget authority."},{"src":"argument","who":"Mr. Kneedler","text":"And I think it's important, the Langston case and that line of cases had been mentioned here. First of all, Langston is the only case in which this Court found liability."},{"src":"argument","who":"Mr. Kneedler","text":"And there's something I want to say when we were talking about the Langston case that -- that very much differs from this context. Langston and that entire line of cases were cases about, as I think I mentioned, employment, salary."}]},{"t":"case","label":"United States v. Mitchell","cite":"109 U.S. 146","y":1883,"id":"scdb/1883-024","sc":1,"by":{"0":"passim","1":"passim","2":"passim","3":"44"},"q":[{"src":"brief","b":0,"text":"[w]hether an appropriations bill impliedly suspends or repeals substantive law ‘depends on the intention of [C]ongress as expressed in the statutes.’","cite":"109 U.S. 146, 150"},{"src":"brief","b":0,"text":"The whole question depends on the intention of Congress as expressed in the statutes.","cite":"109 U.S. at 150"},{"src":"brief","b":2,"text":"the intention of [C]ongress as expressed in the statutes.","cite":"109 U.S. 146, 150"},{"src":"brief","b":3,"text":"The whole question depends on the intention of Congress as expressed in the statutes,","cite":"109 U.S. 146, 150"}]},{"t":"case","label":"United States v. Mitchell","cite":"463 U.S. 206","y":1983,"id":"1982/81-1748","sc":1,"by":{"0":"24, 26","4":"18, 19","5":"15","6":"19"},"q":[{"src":"brief","b":6,"text":"furthers the purposes of the statutes and regulations.","cite":"463 U.S. at 226"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"[n]ot every claim invoking the Constitution, a federal statute, or a regulation is cognizable under the Tucker Act.","cite":"463 U. S., at 216"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"fairly be interpreted as mandating compensation by the Federal Government.","cite":"463 U. S., at 216"}]},{"t":"case","label":"x United States v. St. Louis, S.F. & T.Ry. Co.","cite":"270 U.S. 1","y":1926,"id":"scdb/1925-177","sc":1,"by":{"0":"45"}},{"t":"case","label":"United States v. Testan","cite":"424 U.S. 392","y":1976,"id":"1975/74-753","sc":1,"by":{"0":"24","4":"5, 18, 19"}},{"t":"case","label":"United States v. Vulte","cite":"233 U.S. 509","y":1914,"id":"scdb/1913-145","sc":1,"by":{"0":"49","1":"passim","2":"28, 29, 30, 31","3":"50","6":"24"},"q":[{"src":"brief","b":1,"text":"unless it is expressed in the most clear and positive terms, and where the language admits of no other reasonable interpretation.","cite":"233 U.S. at 515"},{"src":"brief","b":3,"text":"more than the mere omission to appropriate a sufficient sum,","cite":"233 U.S. 509, 515"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"no words were used to indicate any other purpose than the disbursement of a sum of money for the particular fscal years.","cite":"233 U. S., at 514"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"mere omission to appropriate a suffcient sum.","cite":"233 U. S., at 515"}]},{"t":"case","label":"United States v. Will","cite":"449 U.S. 200","y":1980,"id":"1980/79-983","sc":1,"by":{"0":"passim","1":"passim","2":"passim","3":"44, 46, 47","5":"4, 15","6":"22"},"q":[{"src":"brief","b":2,"text":"‘especial force’ when the alleged repeal occurred in an appropriations bill,","cite":"449 U.S. 200, 221-22"},{"src":"brief","b":2,"text":"the rules of both Houses limit the ability to change substantive law through appropriations measures.","cite":"449 U.S. at 222"},{"src":"brief","b":3,"text":"[W]hen Congress desires to suspend or repeal a statute in force, ‘there can be no doubt that . . . it c[an] accomplish its purpose by an amendment to an appropriation bill, or otherwise.’","cite":"449 U.S. 200, 222"},{"src":"brief","b":3,"text":"consign risk corridors payments ‘to the fiscal limbo of an account due but not payable.’","cite":"449 U.S. at 224"},{"src":"argument","who":"Mr. Clement","text":"But the other way to look at that is, if you look at cases like Langston, like Dickerson, like Will, in the original statute that provided for a salary or provided for a payment, none of those original statutes had language that talked specifically about budget authority."},{"src":"argument","who":"Mr. Clement","text":"The cases like Dickerson and Will, they were talking about prospective obligations for the next year. When this Court has confronted cases where the government was saying that it didn't have to pay for past obligations, cases like the Twenty Per Cent Cases and the Larionoff case that are cited in the reply brief of Land of Lincoln, the government never won those cases."},{"src":"argument","who":"Mr. Kneedler","text":"All of the cases in the Langston line of cases all the way up to Will were about salaries. And there is, I think, a sense, and it's now, for example, in the civil service code, a government employee is entitled to a salary."}]},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"3","1":"2"}},{"t":"usc","label":"28 U.S.C. § 1295","url":"https://www.law.cornell.edu/uscode/text/28/1295","subs":["(a)(3)"],"by":{"0":"3","1":"1"}},{"t":"usc","label":"28 U.S.C. § 1491","url":"https://www.law.cornell.edu/uscode/text/28/1491","subs":["(a)","(a)(1)"],"stext":{"head":"§1491. Claims against United States generally; actions involving Tennessee Valley Authority","paras":[[0,"(a)(1) The United States Court of Federal Claims shall have jurisdiction to render judgment upon any claim against the United States founded either upon the Constitution, or any Act of Congress or any regulation of an executive department, or upon any express or implied contract with the United States, or for liquidated or unliquidated damages in cases not sounding in tort. For the purpose of this paragraph, an express or implied contract with the Army and Air Force Exchange Service, Navy Exchanges, Marine Corps Exchanges, Coast Guard Exchanges, or Exchange Councils of the National Aeronautics and Space Administration shall be considered an express or implied contract with the United States."],[0,"(2) To provide an entire remedy and to complete the relief afforded by the judgment, the court may, as an incident of and collateral to any such judgment, issue orders directing restoration to office or position, placement in appropriate duty or retirement status, and correction of applicable records, and such orders may be issued to any appropriate official of the United States. In any case within its jurisdiction, the court shall have the power to remand appropriate matters to any administrative or executive body or official with such direction as it may deem proper and just. The Court of Federal Claims shall have jurisdiction to render judgment upon any claim by or against, or dispute with, a contractor arising under section 7104(b)(1) of title 41, including a dispute concerning termination of a contract, rights in tangible or intangible property, compliance with cost accounting standards, and other nonmonetary disputes on which a decision of the contracting officer has been issued under section 6 1 of that Act."],[0,"(b)(1) Both the Unites 2 States Court of Federal Claims and the district courts of the United States shall have jurisdiction to render judgment on an action by an interested party objecting to a solicitation by a Federal agency for bids or proposals for a proposed contract or to a proposed award or the award of a contract or any alleged violation of statute or regulation in connection with a procurement or a proposed procurement. Both the United States Court of Federal Claims and the district courts of the United States shall have jurisdiction to entertain such an action without regard to whether suit is instituted before or after the contract is awarded."],[0,"(2) To afford relief in such an action, the courts may award any relief that the court considers proper, including declaratory and injunctive relief except that any monetary relief shall be limited to bid preparation and proposal costs."],[0,"(3) In exercising jurisdiction under this subsection, the courts shall give due regard to the interests of national defense and national security and the need for expeditious resolution of the action."],[0,"(4) In any action under this subsection, the courts shall review the agency's decision pursuant to the standards set forth in section 706 of title 5."],[0,"(5) If an interested party who is a member of the private sector commences an action described in paragraph (1) with respect to a public-private competition conducted under Office of Management and Budget Circular A–76 regarding the performance of an activity or function of a Federal agency, or a decision to convert a function performed by Federal employees to private sector performance without a competition under Office of Management and Budget Circular A–76, then an interested party described in section 3551(2)(B) of title 31 shall be entitled to intervene in that action."],[0,"(6) Jurisdiction over any action described in paragraph (1) arising out of a maritime contract, or a solicitation for a proposed maritime contract, shall be governed by this section and shall not be subject to the jurisdiction of the district courts of the United States under the Suits in Admiralty Act (chapter 309 of title 46) or the Public Vessels Act (chapter 311 of title 46)."],[0,"(c) Nothing herein shall be construed to give the United States Court of Federal Claims jurisdiction of any civil action within the exclusive jurisdiction of the Court of International Trade, or of any action against, or founded on conduct of, the Tennessee Valley Authority, or to amend or modify the provisions of the Tennessee Valley Authority Act of 1933 with respect to actions by or against the Authority."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1491?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3, 16, 21, 25","1":"1","3":"30, 49, 30, 49","4":"passim"},"q":[{"src":"brief","b":3,"text":"any Act of Congress or any regulation of an executive department, or upon any express or implied contract with the United States.","cite":"28 U.S.C. 1491(a)(1)"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"claim[s] against the United States founded either upon the Constitution, or any Act of Congress or any regulation of an executive department, or upon any express or implied contract with the United States, or for liquidated or unliquidated damages in cases not sounding in tort.","cite":"28 U. S. C. § 1491(a)(1)"}]},{"t":"usc","label":"28 U.S.C. § 2517","url":"https://www.law.cornell.edu/uscode/text/28/2517","subs":["(b)"],"by":{"0":"32"},"q":[{"src":"brief","b":0,"text":"[E]very final judgment rendered by the United States Court of Federal Claims against the United States shall be paid out of any general appropriation therefor ….","cite":"28 U.S.C. §2517(b)"}]},{"t":"usc","label":"31 U.S.C. § 1304","url":"https://www.law.cornell.edu/uscode/text/31/1304","subs":["(a)"],"stext":{"head":"§1304. Judgments, awards, and compromise settlements","paras":[[0,"(a) Necessary amounts are appropriated to pay final judgments, awards, compromise settlements, and interest and costs specified in the judgments or otherwise authorized by law when—"],[1,"(1) payment is not otherwise provided for;"],[1,"(2) payment is certified by the Secretary of the Treasury; and"],[1,"(3) the judgment, award, or settlement is payable—"],[2,"(A) under section 2414, 2517, 2672, or 2677 of title 28;"],[2,"(B) under section 3723 of this title;"],[2,"(C) under a decision of a board of contract appeals; or"],[2,"(D) in excess of an amount payable from the appropriations of an agency for a meritorious claim under section 2733, 2733a, or 2734 of title 10, section 715 of title 32, or section 20113 of title 51."],[0,"(b)(1) Interest may be paid from the appropriation made by this section—"],[1,"(A) on a judgment of a district court, only when the judgment becomes final after review on appeal or petition by the United States Government, and then only from the date of filing of the transcript of the judgment with the Secretary of the Treasury through the day before the date of the mandate of affirmance; or"],[1,"(B) on a judgment of the Court of Appeals for the Federal Circuit or the United States Court of Federal Claims under section 2516(b) of title 28, only from the date of filing of the transcript of the judgment with the Secretary of the Treasury through the day before the date of the mandate of affirmance."],[0,"(2) Interest payable under this subsection in a proceeding reviewed by the Supreme Court is not allowed after the end of the term in which the judgment is affirmed."],[0,"(c)(1) A judgment or compromise settlement against the Government shall be paid under this section and sections 2414, 2517, and 2518 1 of title 28 when the judgment or settlement arises out of an express or implied contract made by—"],[1,"(A) the Army and Air Force Exchange Service;"],[1,"(B) the Navy Exchanges;"],[1,"(C) the Marine Corps Exchanges;"],[1,"(D) the Coast Guard Exchanges; or"],[1,"(E) the Exchange Councils of the National Aeronautics and Space Administration."],[0,"(2) The Exchange making the contract shall reimburse the Government for the amount paid by the Government."],[0,"(d) Beginning not later than the date that is 60 days after the date of enactment of the John D. Dingell, Jr. Conservation, Management, and Recreation Act, and unless the disclosure of such information is otherwise prohibited by law or a court order, the Secretary of the Treasury shall make available to the public on a website, as soon as practicable, but not later than 30 days after the date on which a payment under this section is tendered, the following information with regard to that payment:"],[1,"(1) The name of the specific agency or entity whose actions gave rise to the claim or judgment."],[1,"(2) The name of the plaintiff or claimant."],[1,"(3) The name of counsel for the plaintiff or claimant."],[1,"(4) The amount paid representing principal liability, and any amounts paid representing any ancillary liability, including attorney fees, costs, and interest."],[1,"(5) A brief description of the facts that gave rise to the claim."],[1,"(6) The name of the agency that submitted the claim."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/31/1304?type=usc&year=mostrecent&link-type=html"},"by":{"0":"16, 32","3":"29","6":"3, 4"},"q":[{"src":"brief","b":0,"text":"to pay final judgments, awards, compromise settlements, and interest and costs specified in the judgments or otherwise authorized by law when … payment is not otherwise provided for ….","cite":"31 U.S.C. §1304(a)"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"[n]ecessary amounts . . . to pay fnal judgments, awards, compromise settlements, and interest and costs specifed in the judgments or otherwise authorized by law when . . . payment is not otherwise provided for.","cite":"31 U. S. C. § 1304(a)(1)"}]},{"t":"usc","label":"31 U.S.C. § 1341","url":"https://www.law.cornell.edu/uscode/text/31/1341","subs":["(a)(1)(A)","(a)(1)","(a)","(a)(1)(B)"],"stext":{"head":"§1341. Limitations on expending and obligating amounts","paras":[[0,"(a)(1) Except as specified in this subchapter or any other provision of law, an officer or employee of the United States Government or of the District of Columbia government may not—"],[1,"(A) make or authorize an expenditure or obligation exceeding an amount available in an appropriation or fund for the expenditure or obligation;"],[1,"(B) involve either government in a contract or obligation for the payment of money before an appropriation is made unless authorized by law;"],[1,"(C) make or authorize an expenditure or obligation of funds required to be sequestered under section 252 of the Balanced Budget and Emergency Deficit Control Act of 1985; or"],[1,"(D) involve either government in a contract or obligation for the payment of money required to be sequestered under section 252 of the Balanced Budget and Emergency Deficit Control Act of 1985."],[0,"(2) This subsection does not apply to a corporation getting amounts to make loans (except paid in capital amounts) without legal liability of the United States Government."],[0,"(b) An article to be used by an executive department in the District of Columbia that could be bought out of an appropriation made to a regular contingent fund of the department may not be bought out of another amount available for obligation."],[0,"(c)(1) In this subsection—"],[1,"(A) the term \"covered lapse in appropriations\" means any lapse in appropriations that begins on or after December 22, 2018;"],[1,"(B) the term \"District of Columbia public employer\" means—"],[2,"(i) the District of Columbia Courts;"],[2,"(ii) the Public Defender Service for the District of Columbia; or"],[2,"(iii) the District of Columbia government;"],[1,"(C) the term \"employee\" includes an officer; and"],[1,"(D) the term \"excepted employee\" means an excepted employee or an employee performing emergency work, as such terms are defined by the Office of Personnel Management or the appropriate District of Columbia public employer, as applicable."],[0,"(2) Each employee of the United States Government or of a District of Columbia public employer furloughed as a result of a covered lapse in appropriations shall be paid for the period of the lapse in appropriations, and each excepted employee who is required to perform work during a covered lapse in appropriations shall be paid for such work, at the employee's standard rate of pay, at the earliest date possible after the lapse in appropriations ends, regardless of scheduled pay dates, and subject to the enactment of appropriations Acts ending the lapse."],[0,"(3) During a covered lapse in appropriations, each excepted employee who is required to perform work shall be entitled to use leave under chapter 63 of title 5, or any other applicable law governing the use of leave by the excepted employee, for which compensation shall be paid at the earliest date possible after the lapse in appropriations ends, regardless of scheduled pay dates."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/31/1341?type=usc&year=mostrecent&link-type=html"},"by":{"0":"33","3":"9, 9, 9","4":"9, 9, 3, 7","5":"12","6":"14, 16"},"q":[{"src":"brief","b":0,"text":"an officer or employee of the United States Government … may not … make or authorize an expenditure … exceeding an amount available in an appropriation … for the expenditure ….","cite":"31 U.S.C. §1341(a)(1)(A)"},{"src":"brief","b":3,"text":"make or authorize an expenditure or obligation exceeding an amount available in an appropriation or fund for the expenditure or obligation.","cite":"31 U.S.C. 1341(a)(1)(A)"}]},{"t":"usc","label":"42 U.S.C. § 280k","url":"https://www.law.cornell.edu/uscode/text/42/280k","subs":["(a)"],"by":{"0":"28","1":"6","4":"13","6":"5, 4"},"q":[{"src":"brief","b":1,"text":"subject to the availability of appropriations.","cite":"42 U.S.C. § 280k(a)"}]},{"t":"usc","label":"42 U.S.C. § 293k-2","url":"https://www.law.cornell.edu/uscode/text/42/293k-2","subs":["(e)"],"by":{"0":"28","1":"6","4":"13","6":"5"}},{"t":"usc","label":"42 U.S.C. § 1395w-115","url":"https://www.law.cornell.edu/uscode/text/42/1395w-115","subs":["(e)(3)(A)","(a)(2)","(e)(2)(B)"],"stext":{"head":"§1395w–115. Subsidies for part D eligible individuals for qualified prescription drug coverage","paras":[[0,"(a) Subsidy payment"],[0,"In order to reduce premium levels applicable to qualified prescription drug coverage for part D eligible individuals consistent with an overall subsidy level of 74.5 percent (or, for each of 2024 through 2029, the percent applicable as a result of the application of section 1395w–113(a)(8) of this title, or, for 2030 and each subsequent year, 100 percent minus the percent specified under section 1395w–113(a)(9) of this title) for basic prescription drug coverage, to reduce adverse selection among prescription drug plans and MA–PD plans, and to promote the participation of PDP sponsors under this part and MA organizations under part C, the Secretary shall provide for payment to a PDP sponsor that offers a prescription drug plan and an MA organization that offers an MA–PD plan of the following subsidies in accordance with this section:"],[0,"(1) Direct subsidy"],[1,"A direct subsidy for each part D eligible individual enrolled in a prescription drug plan or MA–PD plan for a month equal to—"],[2,"(A) the amount of the plan's standardized bid amount (as defined in section 1395w–113(a)(5) of this title), adjusted under subsection (c)(1), reduced by"],[2,"(B) the base beneficiary premium (as computed under paragraph (2) or (8) of section 1395w–113(a) of this title (as applicable) and as adjusted under paragraph (1)(B) of such section)."],[0,"(2) Subsidy through reinsurance"],[1,"The reinsurance payment amount (as defined in subsection (b))."],[0,"This section constitutes budget authority in advance of appropriations Acts and represents the obligation of the Secretary to provide for the payment of amounts provided under this section."],[0,"(b) Reinsurance payment amount"],[0,"(1) In general"],[1,"The reinsurance payment amount under this subsection for a part D eligible individual enrolled in a prescription drug plan or MA–PD plan for a coverage year is an amount equal to—"],[2,"(A) for a year preceding 2025, 80 percent of the allowable reinsurance costs (as specified in paragraph (2)) attributable to that portion of gross covered prescription drug costs as specified in paragraph (3) incurred in the coverage year after such individual has incurred costs that exceed the annual out-of-pocket threshold specified in section 1395w–102(b)(4)(B) of this title; and"],[2,"(B) for 2025 and each subsequent year, the sum of—"],[3,"(i) with respect to applicable drugs (as defined in section 1395w–114c(g)(2) of this title), an amount equal to 20 percent of such allowable reinsurance costs attributable to that portion of gross covered prescription drug costs as specified in paragraph (3) incurred in the coverage year after such individual has incurred costs that exceed the annual out-of-pocket threshold specified in section 1395w–102(b)(4)(B) of this title; and"],[3,"(ii) with respect to covered part D drugs that are not applicable drugs (as so defined), an amount equal to 40 percent of such allowable reinsurance costs attributable to that portion of gross covered prescription drug costs as specified in paragraph (3) incurred in the coverage year after such individual has incurred costs that exceed the annual out-of-pocket threshold specified in section 1395w–102(b)(4)(B) of this title."],[0,"(2) Allowable reinsurance costs"],[0,"(A) In general"],[2,"Subject to subparagraph (B), for purposes of this section, the term \"allowable reinsurance costs\" means, with respect to gross covered prescription drug costs under a prescription drug plan offered by a PDP sponsor or an MA–PD plan offered by an MA organization, the part of such costs that are actually paid (net of discounts, chargebacks, and average percentage rebates) by the sponsor or organization or by (or on behalf of) an enrollee under the plan, but in no case more than the part of such costs that would have been paid under the plan if the prescription drug coverage under the plan were basic prescription drug coverage, or, in the case of a plan providing supplemental prescription drug coverage, if such coverage were standard prescription drug coverage."],[0,"(B) Inclusion of manufacturer discounts on applicable drugs"],[2,"For purposes of applying subparagraph (A), the term \"allowable reinsurance costs\" shall include the portion of the negotiated price (as defined in section 1395w–114c(g)(6) of this title) of an applicable drug (as defined in section 1395w–114c(g)(2) of this title) that was paid by a manufacturer under the manufacturer discount program under section 1395w–114c of this title."],[0,"(3) Gross covered prescription drug costs"],[1,"Subject to paragraph (2)(B), for purposes of this section, the term \"gross covered prescription drug costs\" means, with respect to a part D eligible individual enrolled in a prescription drug plan or MA–PD plan during a coverage year, the costs incurred under the plan, not including administrative costs, but including costs directly related to the dispensing of covered part D drugs during the year and costs relating to the deductible. Such costs shall be determined whether they are paid by the individual or under the plan (or, with respect to 2025 and subsequent years, in the case of an applicable drug, as defined in section 1395w–114c(g)(2) of this title, by a manufacturer), regardless of whether the coverage under the plan exceeds basic prescription drug coverage."],[0,"(4) Coverage year defined"],[1,"For purposes of this section, the term \"coverage year\" means a calendar year in which covered part D drugs are dispensed if the claim for such drugs (and payment on such claim) is made not later than such period after the end of such year as the Secretary specifies."],[0,"(c) Adjustments relating to bids"],[0,"(1) Health status risk adjustment"],[0,"(A) Establishment of risk adjustors"],[2,"The Secretary shall establish an appropriate methodology for adjusting the standardized bid amount under subsection (a)(1)(A) to take into account variation in costs for basic prescription drug coverage among prescription drug plans and MA–PD plans based on the differences in actuarial risk of different enrollees being served. Any such risk adjustment shall be designed in a manner so as not to result in a change in the aggregate amounts payable to such plans under subsection (a)(1) and through that portion of the monthly beneficiary prescription drug premiums described in subsection (a)(1)(B) and MA monthly prescription drug beneficiary premiums."],[0,"(B) Considerations"],[2,"In establishing the methodology under subparagraph (A), the Secretary may take into account the similar methodologies used under section 1395w–23(a)(3) of this title to adjust payments to MA organizations for benefits under the original medicare fee-for-service program option."],[0,"(C) Data collection"],[2,"In order to carry out this paragraph, the Secretary shall require—"],[3,"(i) PDP sponsors to submit data regarding drug claims that can be linked at the individual level to part A and part B data and such other information as the Secretary determines necessary; and"],[3,"(ii) MA organizations that offer MA–PD plans to submit data regarding drug claims that can be linked at the individual level to other data that such organizations are required to submit to the Secretary and such other information as the Secretary determines necessary."],[0,"(D) Publication"],[2,"At the time of publication of risk adjustment factors under section 1395w–23(b)(1)(B)(i)(II) of this title, the Secretary shall publish the risk adjusters established under this paragraph for the succeeding year."],[0,"(2) Geographic adjustment"],[0,"(A) In general"],[2,"Subject to subparagraph (B), for purposes of section 1395w–113(a)(1)(B)(iii) of this title, the Secretary shall establish an appropriate methodology for adjusting the national average monthly bid amount (computed under section 1395w–113(a)(4) of this title) to take into account differences in prices for covered part D drugs among PDP regions."],[0,"(B) De minimis rule"],[2,"If the Secretary determines that the price variations described in subparagraph (A) among PDP regions are de minimis, the Secretary shall not provide for adjustment under this paragraph."],[0,"(C) Budget neutral adjustment"],[2,"Any adjustment under this paragraph shall be applied in a manner so as to not result in a change in the aggregate payments made under this part that would have been made if the Secretary had not applied such adjustment."],[0,"(d) Payment methods"],[0,"(1) In general"],[1,"Payments under this section shall be based on such a method as the Secretary determines. The Secretary may establish a payment method by which interim payments of amounts under this section are made during a year based on the Secretary's best estimate of amounts that will be payable after obtaining all of the information."],[0,"(2) Requirement for provision of information"],[0,"(A) Requirement"],[2,"Payments under this section to a PDP sponsor or MA organization are conditioned upon the furnishing to the Secretary, in a form and manner specified by the Secretary, of such information as may be required to carry out this section."],[0,"(B) Restriction on use of information"],[2,"Information disclosed or obtained pursuant to subparagraph (A) may be used by officers, employees, and contractors of the Department of Health and Human Services only for the purposes of, and to the extent necessary in, carrying out this section."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1395w-115?type=usc&year=mostrecent&link-type=html"},"by":{"0":"26","1":"7","2":"8","3":"31, 31","4":"13, 14","5":"17","6":"6"},"q":[{"src":"brief","b":3,"text":"[t]his section constitutes budget authority in advance of appropriations Acts and represents the obligation of the Secretary [of HHS] to provide for the payment of amounts provided under this section.","cite":"42 U.S.C. 1395w-115(a)(2)"},{"src":"brief","b":3,"text":"to provide for the payment of amounts provided under this section.","cite":"42 U.S.C. 1395w-115(a)(2)"}]},{"t":"usc","label":"42 U.S.C. § 1397m-1","url":"https://www.law.cornell.edu/uscode/text/42/1397m-1","subs":["(b)(2)(A)"],"by":{"0":"28","1":"6","4":"13","6":"5"}},{"t":"usc","label":"42 U.S.C. § 18042","url":"https://www.law.cornell.edu/uscode/text/42/18042","subs":["(g)"],"by":{"0":"8","3":"6, 8, 15, 23"}},{"t":"usc","label":"42 U.S.C. § 18062","url":"https://www.law.cornell.edu/uscode/text/42/18062","subs":["(a)","(b)(1)","(b)(2)"],"stext":{"head":"§18062. Establishment of risk corridors for plans in individual and small group markets","paras":[[0,"(a) In general"],[0,"The Secretary shall establish and administer a program of risk corridors for calendar years 2014, 2015, and 2016 under which a qualified health plan offered in the individual or small group market shall participate in a payment adjustment system based on the ratio of the allowable costs of the plan to the plan's aggregate premiums. Such program shall be based on the program for regional participating provider organizations under part D of title XVIII of the Social Security Act [42 U.S.C. 1395w–101 et seq.]."],[0,"(b) Payment methodology"],[0,"(1) Payments out"],[1,"The Secretary shall provide under the program established under subsection (a) that if—"],[2,"(A) a participating plan's allowable costs for any plan year are more than 103 percent but not more than 108 percent of the target amount, the Secretary shall pay to the plan an amount equal to 50 percent of the target amount in excess of 103 percent of the target amount; and"],[2,"(B) a participating plan's allowable costs for any plan year are more than 108 percent of the target amount, the Secretary shall pay to the plan an amount equal to the sum of 2.5 percent of the target amount plus 80 percent of allowable costs in excess of 108 percent of the target amount."],[0,"(2) Payments in"],[1,"The Secretary shall provide under the program established under subsection (a) that if—"],[2,"(A) a participating plan's allowable costs for any plan year are less than 97 percent but not less than 92 percent of the target amount, the plan shall pay to the Secretary an amount equal to 50 percent of the excess of 97 percent of the target amount over the allowable costs; and"],[2,"(B) a participating plan's allowable costs for any plan year are less than 92 percent of the target amount, the plan shall pay to the Secretary an amount equal to the sum of 2.5 percent of the target amount plus 80 percent of the excess of 92 percent of the target amount over the allowable costs."],[0,"(c) Definitions"],[0,"In this section:"],[0,"(1) Allowable costs"],[0,"(A) In general"],[2,"The amount of allowable costs of a plan for any year is an amount equal to the total costs (other than administrative costs) of the plan in providing benefits covered by the plan."],[0,"(B) Reduction for risk adjustment and reinsurance payments"],[2,"Allowable costs shall 1 reduced by any risk adjustment and reinsurance payments received under section 2 18061 and 18063 of this title."],[0,"(2) Target amount"],[1,"The target amount of a plan for any year is an amount equal to the total premiums (including any premium subsidies under any governmental program), reduced by the administrative costs of the plan."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/18062?type=usc&year=mostrecent&link-type=html"},"by":{"0":"passim","1":"passim","2":"5, 6, 8, 34","3":"passim, 6, 8, 15, 23, 6, 8, 15, 23, 7, 7","4":"passim","6":"passim, 4, 4, 4"},"q":[{"src":"brief","b":2,"text":"establish and administer a program of risk corridors for calendar years 2014, 2015, and 2016.","cite":"42 U.S.C. §18062"},{"src":"brief","b":3,"text":"shall participate in a payment adjustment system based on the ratio of the allowable costs of the plan to the plan’s aggregate premiums.","cite":"42 U.S.C. 18062(a)"}]},{"t":"law","label":"Pub. L. No. 113-235","url":"https://www.govinfo.gov/link/plaw/113/public/235","by":{"0":"14, 35, 51","1":"24, 25","2":"14, 30","5":"4"}},{"t":"law","label":"Pub. L. No. 114-113","url":"https://www.govinfo.gov/link/plaw/114/public/113","by":{"0":"14, 51","1":"25","2":"14, 30","3":"10","5":"4"}},{"t":"law","label":"Pub. L. No. 115-31","url":"https://www.govinfo.gov/link/plaw/115/public/31","by":{"0":"14","2":"14, 30","3":"10","5":"4"}},{"t":"law","label":"Pub. L. No. 115-141","url":"https://www.govinfo.gov/link/plaw/115/public/141","by":{"0":"15","2":"15"}},{"t":"reg","label":"45 C.F.R. § 147.106","url":"https://www.ecfr.gov/current/title-45/section-147.106","subs":["(b)","(d)"],"by":{"0":"9, 9"}},{"t":"reg","label":"Federal Register, 77 Fed. Reg. 17,220","url":"https://www.govinfo.gov/link/fr/77/17220","by":{"0":"5","2":"7"}},{"t":"reg","label":"78 Fed. Reg. 15,410","url":"https://www.govinfo.gov/link/fr/78/15410","by":{"0":"11","1":"7","2":"8, 37","5":"9"}},{"t":"reg","label":"79 Fed. Reg. 13,744","url":"https://www.govinfo.gov/link/fr/79/13744","by":{"0":"11"}},{"t":"reg","label":"79 Fed. Reg. 30,240","url":"https://www.govinfo.gov/link/fr/79/30240","by":{"0":"12","2":"14"}},{"t":"reg","label":"80 Fed. Reg. 10,750","url":"https://www.govinfo.gov/link/fr/80/10750","by":{"0":"12","1":"12","2":"16","4":"10"}},{"t":"case","label":"Andrus v. Sierra Club","cite":"442 U.S. 347","y":1979,"id":"1978/78-625","sc":1,"by":{"1":"23","3":"21"},"q":[{"src":"brief","b":3,"text":"‘represent limitations of amounts which agencies may obligate during the time period specified in the respective appropriations acts.’","cite":"442 U.S. 347, 359 n.18"}]},{"t":"case","label":"Carcieri v. Salazar","cite":"555 U.S. 379","y":2009,"id":"2008/07-526","sc":1,"by":{"1":"22"},"q":[{"src":"brief","b":1,"text":"absent a clearly expressed congressional intention, an implied repeal will only be found where provisions in two statutes are in irreconcilable conflict, or where the latter Act covers the whole subject of the earlier one and is clearly intended as a substitute.","cite":"555 U.S. 379, 395"}]},{"t":"case","label":"Carter v. United States","cite":"530 U.S. 255","y":2000,"id":"1999/99-5716","sc":1,"by":{"1":"38"},"q":[{"src":"brief","b":1,"text":"by examining the text, not by ‘psychoanalyzing those who enacted it.’","cite":"530 U.S. 255, 271"}]},{"t":"case","label":"Cherokee Nation of Oklahoma v. Leavitt","cite":"543 U.S. 631","y":2005,"id":"2004/02-1472","sc":1,"by":{"1":"28, 36","3":"37, 56","5":"10","6":"passim"},"q":[{"src":"brief","b":1,"text":"appropriated ‘not to exceed’ a given amount . . ., thereby imposing an express cap on the total funds available.","cite":"543 U.S. 631"},{"src":"brief","b":3,"text":"‘uses the word ‘contract’ 426 times to describe the nature of the Government’s promise.’","cite":"543 U.S. 631, 639"},{"src":"brief","b":3,"text":"officer cannot bind the Government in the absence of an appropriation.","cite":"543 U.S. at 643"},{"src":"argument","who":"Mr. Clement","text":"Again, Justice Breyer for the Court noted that there was a potential constitutional problem with retroactive legislation of this type in the Cherokee Nation case."}]},{"t":"case","label":"Chevron, U.S.A., Inc. v. Natural Resources Defense Council, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"by":{"1":"27"}},{"t":"case","label":"Christensen v. Harris County","cite":"529 U.S. 576","y":2000,"id":"1999/98-1167","sc":1,"by":{"1":"27"}},{"t":"case","label":"Claridge Apartments Co. v. Comm’r of Internal Revenue","cite":"323 U.S. 141","y":1944,"id":"scdb/1944-011","sc":1,"by":{"1":"43"}},{"t":"case","label":"De Niz Robles v. Lynch","cite":"803 F.3d 1165","y":2015,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/803/1165/","by":{"1":"43"},"q":[{"src":"brief","b":1,"text":"[L]egislation is rarely afforded retroactive effect. . . . Indeed, the presumption is sometimes said to inhere in the very meaning of the ‘legislative Powers’ the framers assigned to Congress in Article I of our Constitution.","cite":"803 F.3d 1165, 1169-70"}]},{"t":"case","label":"Dowling v. U.S. Dep’t of Health and Human Servs.","cite":"325 F. Supp. 3d 884","y":2018,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/325/884/","by":{"1":"43"},"q":[{"src":"brief","b":1,"text":"[s]ome policyholders were placed in the unenviable position of finding short-term health coverage and restarting their co-payment and deductible amounts from zero.","cite":"325 F. Supp. 3d 884, 898"}]},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"138 S. Ct. 1612","y":2018,"id":"2017/16-285","sc":1,"by":{"1":"22, 26, 35","2":"28, 33, 54","5":"3"},"q":[{"src":"brief","b":1,"text":"[L]egislative history is not the law.","cite":"138 S. Ct. at 1631"},{"src":"brief","b":2,"text":"[a] party seeking to suggest that two statutes cannot be harmonized, and that one displaces the other, bears the heavy burden of showing ‘a clearly expressed congressional intention’ that such a result should follow.","cite":"138 S. Ct. at 1624"},{"src":"brief","b":2,"text":"legislative history is not the law.","cite":"138 S. Ct. at 1631"}]},{"t":"case","label":"Exxon Mobil Corp. v. Allapattah Servs., Inc.","cite":"545 U.S. 546","y":2005,"id":"2004/04-70","sc":1,"by":{"1":"35","2":"34"},"q":[{"src":"brief","b":1,"text":"committee members — or, worse yet, unelected staffers and lobbyists — [with] both the power and the incentive to . . . manipulat[e] . . . legislative history to secure results they were unable to achieve through the statutory text.","cite":"545 U.S. 546, 568"},{"src":"brief","b":2,"text":"unrepresentative committee members—or, worse yet, unelected staffers and lobbyists—[with] both the power and the incentive to attempt strategic manipulations of legislative history to secure results they were unable to achieve through the statutory text.","cite":"545 U.S. 546, 568"}]},{"t":"case","label":"Gonzales v. Oregon","cite":"546 U.S. 243","y":2006,"id":"2005/04-623","sc":1,"by":{"1":"26"}},{"t":"case","label":"King v. Burwell","cite":"135 S. Ct. 2480","y":2015,"id":"2014/14-114","sc":1,"by":{"1":"48","3":"4, 5, 28"}},{"t":"case","label":"Land of Lincoln Mut. Health Ins. Co. v. United States","cite":"129 Fed. Cl. 81","y":2016,"url":"https://www.courtlistener.com/c/Fed.%20Cl./129/81/","by":{"1":"1","2":"59","5":"11"}},{"t":"case","label":"Land of Lincoln Mut. Health Ins. Co. v. United States","cite":"892 F.3d 1184","y":2018,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/892/1184/","by":{"1":"1"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"for each of the applicable years","cite":"892 F. 3d, at 1325"}]},{"t":"case","label":"Lynch v. United States","cite":"292 U.S. 571","y":1934,"id":"scdb/1933-150","sc":1,"by":{"1":"52","2":"53"},"q":[{"src":"brief","b":1,"text":"[r]ights against the United States arising out of a contract with [the United States] are protected by the Fifth Amendment.","cite":"292 U.S. 571, 579"},{"src":"brief","b":2,"text":"[w]hen the United States enters into contract relations, its rights and duties therein are governed generally by the law applicable to contracts between private individuals.","cite":"292 U.S. 571, 579"}]},{"t":"case","label":"Metroil, Inc. v. ExxonMobil Oil Corp.","cite":"672 F.3d 1108","y":2012,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/672/1108/","by":{"1":"43"}},{"t":"case","label":"Mobil Oil Expl. & Producing Serv., Inc. v. United States","cite":"530 U.S. 604","y":2000,"id":"1999/99-244","sc":1,"by":{"1":"52","2":"52, 53"}},{"t":"case","label":"Nat’l R.R. Passenger Corp. v. Atchison Topeka & Santa Fe Ry. Co.","cite":"470 U.S. 451","y":1985,"id":"1984/83-1492","sc":1,"by":{"1":"51","2":"51","3":"17, 35, 36, 53","5":"9"},"q":[{"src":"brief","b":1,"text":"clear indication that the legislature intend[ed] to bind itself contractually.","cite":"470 U.S. 451, 465-66"},{"src":"brief","b":2,"text":"clear indication that the legislature intend[ed] to bind itself contractually.","cite":"470 U.S. 451, 465-66"},{"src":"brief","b":3,"text":"clear indication that the legislature intends to bind itself contractually.","cite":"470 U.S. 451, 465-466"},{"src":"brief","b":3,"text":"[A]bsent some clear indication that the legislature intends to bind itself contractually, the presumption is that ‘a law is not intended to create private contractual or vested rights but merely declares a policy to be pursued until the legislature shall ordain otherwise.’","cite":"470 U.S. 451, 465-466"}]},{"t":"case","label":"New Prime Inc. v. Oliveira","cite":"139 S. Ct. 532","y":2019,"id":"2018/17-340","sc":1,"by":{"1":"37","6":"23"},"q":[{"src":"brief","b":1,"text":"If courts felt free to pave over bumpy statutory texts . . ., [they] would risk failing to ‘tak[e] . . . account of ’ legislative compromises essential to a law’s passage and, in that way, thwart rather than honor ‘the effectuation of congressional intent.’","cite":"139 S. Ct. 532, 543"}]},{"t":"case","label":"NLRB v. SW Gen., Inc.","cite":"137 S. Ct. 929","y":2017,"id":"2016/15-1251","sc":1,"by":{"1":"39"},"q":[{"src":"brief","b":1,"text":"[F]loor statements by individual legislators rank among the least illuminating forms of legislative history.","cite":"137 S. Ct. 929, 943"}]},{"t":"case","label":"Robertson v. Seattle Audubon Soc.","cite":"503 U.S. 429","y":1992,"id":"1991/90-1596","sc":1,"by":{"1":"23"}},{"t":"case","label":"St. Martin Evangelical Lutheran Church v. South Dakota","cite":"451 U.S. 772","y":1981,"id":"1980/80-120","sc":1,"by":{"1":"21, 45"},"q":[{"src":"brief","b":1,"text":"Court has had frequent occasion to note that . . . indefinite congressional expressions cannot negate plain statutory language and cannot work a repeal or amendment by implication.","cite":"451 U.S. 772, 78788"},{"src":"brief","b":1,"text":"carries special weight when an implied repeal or amendment might raise constitutional questions.","cite":"451 U.S. at 788"}]},{"t":"case","label":"Union Pac. R. Co. v. Laramie Stock Yards Co.","cite":"231 U.S. 190","y":1913,"id":"scdb/1913-023","sc":1,"by":{"1":"43"}},{"t":"case","label":"United States v. Larionoff","cite":"431 U.S. 864","y":1977,"id":"1976/76-413","sc":1,"by":{"1":"44, 45","6":"25"},"q":[{"src":"argument","who":"Mr. Clement","text":"When this Court has confronted cases where the government was saying that it didn't have to pay for past obligations, cases like the Twenty Per Cent Cases and the Larionoff case that are cited in the reply brief of Land of Lincoln, the government never won those cases."}]},{"t":"case","label":"United States v. Mead Corp.","cite":"533 U.S. 218","y":2001,"id":"2000/99-1434","sc":1,"by":{"1":"27"}},{"t":"case","label":"United States v. Northern Pacific Railway Co.","cite":"256 U.S. 51","y":1921,"id":"scdb/1920-129","sc":1,"by":{"1":"51","6":"26"}},{"t":"case","label":"United States v. Security Industrial Bank","cite":"459 U.S. 70","y":1982,"id":"1982/81-184","sc":1,"by":{"1":"45"}},{"t":"case","label":"United States v. United States Gypsum Co.","cite":"438 U.S. 422","y":1978,"id":"1977/76-1560","sc":1,"by":{"1":"30"},"q":[{"src":"brief","b":1,"text":"Congress will be presumed to have legislated against the background of our traditional legal concepts.","cite":"438 U.S. 422, 437"}]},{"t":"case","label":"United States v. Winstar Corp.","cite":"518 U.S. 839","y":1996,"id":"1995/95-865","sc":1,"by":{"1":"49","2":"52, 53, 57, 58","6":"4, 25"},"q":[{"src":"brief","b":1,"text":"[a] promise to pay, 29 See Moshe Schwartz et al., Congressional Research Service, Defense Acquisitions: How and Where DOD Spends Its Contracting Dollars, R44010, at 2 (July 2, 2018). with a reserved right to deny or change the effect of the promise, is an absurdity.","cite":"518 U.S. 839, 913"},{"src":"brief","b":1,"text":"[i]t is no less good morals and good law that the Government should turn square corners in dealing with the people than that the people should turn square corners in dealing with their government.","cite":"518 U.S. at 886 n.31"},{"src":"argument","who":"Mr. Clement","text":"Well, look, I -- I don't -- I mean, if -- it's a contract case, but, if you cut right down to it and you adjust for inflation, I would think Winstar got you into the billions of dollars as well."},{"src":"argument","who":"Justice Breyer","text":"How did we decide Winstar? I -- I remember staying here until July and somebody over the government had promised all those banks that if they did dah, dah, dah, they'd get paid about a billion dollars."}]},{"t":"case","label":"Vartelas v. Holder","cite":"566 U.S. 257","y":2012,"id":"2011/10-1211","sc":1,"by":{"1":"43"},"q":[{"src":"brief","b":1,"text":"The presumption against retroactive legislation . . . ‘embodies a legal doctrine centuries older than our Republic.’","cite":"566 U.S. 257, 265"}]},{"t":"case","label":"Whitman v. Am. Trucking Ass’ns","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"by":{"1":"26"}},{"t":"usc","label":"42 U.S.C. § 1395w-4","url":"https://www.law.cornell.edu/uscode/text/42/1395w-4","by":{"1":"6"},"q":[{"src":"brief","b":1,"text":"shall be implemented in a budget neutral manner[,]","cite":"42 U.S.C. § 1395w-4(p)(4)(C)"}]},{"t":"usc","label":"42 U.S.C. § 18061","url":"https://www.law.cornell.edu/uscode/text/42/18061","by":{"1":"4, 7","3":"6, 5"}},{"t":"usc","label":"42 U.S.C. § 18063","url":"https://www.law.cornell.edu/uscode/text/42/18063","by":{"1":"4","3":"6"}},{"t":"usc","label":"42 U.S.C. § 300hh-31","url":"https://www.law.cornell.edu/uscode/text/42/300hh-31","by":{"1":"6","6":"5"}},{"t":"reg","label":"45 C.F.R. § 153.510","url":"https://www.ecfr.gov/current/title-45/section-153.510","by":{"1":"7"}},{"t":"reg","label":"77 Fed. Reg. 17,251","url":"https://www.govinfo.gov/link/fr/77/17251","by":{"1":"7"}},{"t":"reg","label":"78 Fed. Reg. 15,413","url":"https://www.govinfo.gov/link/fr/78/15413","by":{"1":"46-47"}},{"t":"reg","label":"78 Fed. Reg. 15,441","url":"https://www.govinfo.gov/link/fr/78/15441","by":{"1":"7"}},{"t":"reg","label":"78 Fed. Reg. 15,473","url":"https://www.govinfo.gov/link/fr/78/15473","by":{"1":"7"}},{"t":"reg","label":"79 Fed. Reg. 13,746","url":"https://www.govinfo.gov/link/fr/79/13746","by":{"1":"40"}},{"t":"reg","label":"79 Fed. Reg. 13,786","url":"https://www.govinfo.gov/link/fr/79/13786","by":{"1":"40"}},{"t":"reg","label":"79 Fed. Reg. 13,787","url":"https://www.govinfo.gov/link/fr/79/13787","by":{"1":"39"}},{"t":"reg","label":"79 Fed. Reg. 30,260","url":"https://www.govinfo.gov/link/fr/79/30260","by":{"1":"9","2":"14","6":"9"}},{"t":"reg","label":"80 Fed. Reg. 10,779","url":"https://www.govinfo.gov/link/fr/80/10779","by":{"1":"12"}},{"t":"case","label":"Bank Markazi v. Peterson","cite":"136 S. Ct. 1310","y":2016,"id":"2015/14-770","sc":1,"by":{"2":"47"}},{"t":"case","label":"Belknap v. United States","cite":"150 U.S. 588","y":1893,"id":"scdb/1893-068","sc":1,"by":{"2":"30, 39","3":"51","5":"15"},"q":[{"src":"brief","b":2,"text":"not, in and of itself alone, sufficient to repeal the prior act.","cite":"150 U.S. 588, 594"},{"src":"argument","who":"Mr. Kneedler","text":"And seven years later, in the Belknap case, the Court said that's as far as we're going to go. And in -- in Langston, what was critical is the Court found the appropriations language ambiguous."}]},{"t":"case","label":"Cook Cty. v. United States ex rel. Chandler","cite":"538 U.S. 119","y":2003,"id":"2002/01-1572","sc":1,"by":{"2":"28"}},{"t":"case","label":"E. Enters. v. Apfel","cite":"524 U.S. 498","y":1998,"id":"1997/97-42","sc":1,"by":{"2":"47, 48"},"q":[{"src":"brief","b":2,"text":"[b]oth stability of investment and confidence in the constitutional system.","cite":"524 U.S. 498, 549"}]},{"t":"case","label":"Fourth Estate Pub. Benefit Corp. v. Wall-Street.com, LLC","cite":"139 S. Ct. 881","y":2019,"id":"2018/17-571","sc":1,"by":{"2":"37"}},{"t":"case","label":"Free Enter. Fund v. Public Co. Accounting Oversight Bd.","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"by":{"2":"56"}},{"t":"case","label":"INS v. Chadha","cite":"462 U.S. 919","y":1983,"id":"1981/80-1832","sc":1,"by":{"2":"33, 54"},"q":[{"src":"brief","b":2,"text":"only after opportunity for full study and debate.","cite":"462 U.S. at 951, 959"}]},{"t":"case","label":"Murr v. Wisconsin","cite":"137 S. Ct. 1933","y":2017,"id":"2016/15-214","sc":1,"by":{"2":"48"}},{"t":"case","label":"New York v. United States","cite":"505 U.S. 144","y":1992,"id":"1991/91-543","sc":1,"by":{"2":"55"},"q":[{"src":"brief","b":2,"text":"in full view of the public, and … suffer the consequences if the decision turns out to be detrimental or unpopular.","cite":"505 U.S. 144, 168"}]},{"t":"case","label":"Penn Cent. Transp. Co. v. City of N.Y.","cite":"438 U.S. 104","y":1978,"id":"1977/77-444","sc":1,"by":{"2":"48"},"q":[{"src":"brief","b":2,"text":"has interfered with distinct investment-backed expectations","cite":"438 U.S. 104, 124"}]},{"t":"case","label":"Plaut v. Spendthrift Farm, Inc.","cite":"514 U.S. 211","y":1995,"id":"1994/93-1121","sc":1,"by":{"2":"49"},"q":[{"src":"brief","b":2,"text":"prolonged reticence would be amazing if such interference were not understood to be constitutionally proscribed.","cite":"514 U.S. at 230"}]},{"t":"case","label":"Printz v. United States","cite":"521 U.S. 898","y":1997,"id":"1996/95-1478","sc":1,"by":{"2":"49"}},{"t":"case","label":"Schwegmann Bros. v. Calvert Distillers Corp.","cite":"341 U.S. 384","y":1951,"id":"scdb/1950-082","sc":1,"by":{"2":"35"},"q":[{"src":"brief","b":2,"text":"the cost of repeatedly examining the whole congressional history","cite":"341 U.S. 384, 396"}]},{"t":"case","label":"Shannon v. United States","cite":"512 U.S. 573","y":1994,"id":"1993/92-8346","sc":1,"by":{"2":"36"}},{"t":"case","label":"United States v. Borden Co.","cite":"308 U.S. 188","y":1939,"id":"scdb/1939-008","sc":1,"by":{"2":"28"}},{"t":"case","label":"United States v. Bostwick","cite":"94 U.S. 53","y":1876,"id":"scdb/1876-108","sc":1,"by":{"2":"53"}},{"t":"case","label":"United States v. Kwai Fun Wong","cite":"135 S. Ct. 1625","y":2015,"id":"2014/13-1074","sc":1,"by":{"2":"35"},"q":[{"src":"brief","b":2,"text":"even assuming legislative history alone could provide a clear statement (which we doubt), none does so here.","cite":"135 S. Ct. 1625, 1633"}]},{"t":"case","label":"United States v. R.L.C.","cite":"503 U.S. 291","y":1992,"id":"1991/90-1577","sc":1,"by":{"2":"35"}},{"t":"usc","label":"26 U.S.C. § 36B","url":"https://www.law.cornell.edu/uscode/text/26/36B","by":{"2":"4","3":"5, 55"}},{"t":"usc","label":"42 U.S.C. § 18031","url":"https://www.law.cornell.edu/uscode/text/42/18031","subs":["(a)(1)"],"by":{"2":"3","3":"6","6":"6, 4"}},{"t":"usc","label":"42 U.S.C. § 300gg-94","url":"https://www.law.cornell.edu/uscode/text/42/300gg-94","by":{"2":"11"}},{"t":"law","label":"Pub. L. No. 111-148","url":"https://www.govinfo.gov/link/plaw/111/public/148","by":{"2":"10"}},{"t":"law","label":"Pub. L. No. 115-245","url":"https://www.govinfo.gov/link/plaw/115/public/245","by":{"2":"15"}},{"t":"reg","label":"45 C.F.R. pt. 153","url":"https://www.ecfr.gov/current/title-45/part-153","by":{"2":"6, 7"}},{"t":"reg","label":"45 C.F.R. § 154.200","url":"https://www.ecfr.gov/current/title-45/section-154.200","by":{"2":"11"}},{"t":"reg","label":"48 C.F.R. § 1.102","url":"https://www.ecfr.gov/current/title-48/section-1.102","by":{"2":"56"}},{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"by":{"3":"20"}},{"t":"case","label":"American Bankers Ass’n v. United States","cite":"932 F.3d 1375","y":2019,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/932/1375/","by":{"3":"53"}},{"t":"case","label":"American Fed’n of Gov’t Emps., AFL-CIO v. Federal Labor Relations Auth.","cite":"388 F.3d 405","y":2004,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/388/405/","by":{"3":"21"}},{"t":"case","label":"Bowen v. Public Agencies Opposed to Social Sec. Entrapment","cite":"477 U.S. 41","y":1986,"id":"1985/85-521","sc":1,"by":{"3":"54"}},{"t":"case","label":"Community Health Choice, Inc. v. United States","cite":"141 Fed. Cl. 744","y":2019,"url":"https://www.courtlistener.com/c/Fed.%20Cl./141/744/","by":{"3":"34"}},{"t":"case","label":"Dahda v. United States","cite":"138 S. Ct. 1491","y":2018,"id":"2017/17-43","sc":1,"by":{"3":"20"}},{"t":"case","label":"Dodge v. Board of Educ.","cite":"302 U.S. 74","y":1937,"id":"scdb/1937-020","sc":1,"by":{"3":"35, 54","5":"10"},"q":[{"src":"argument","who":"Mr. Kneedler","text":"Again, I want to come back to the Amtrak case and -- and -- and referring back to the Dodge case as the canonical statement, and that is that an act -- that a statute, an act of Congress, absent clear indications, is not construed to create a contract and is not construed to create vested rights."}]},{"t":"case","label":"Dorsey v. United States","cite":"567 U.S. 260","y":2012,"id":"2011/11-5683","sc":1,"by":{"3":"25"}},{"t":"case","label":"Hall v. Wisconsin","cite":"103 U.S. 5","y":1880,"id":"scdb/1880-017","sc":1,"by":{"3":"53"}},{"t":"case","label":"Indiana ex rel. Anderson v. Brand","cite":"303 U.S. 95","y":1938,"id":"scdb/1937-096","sc":1,"by":{"3":"54"}},{"t":"case","label":"Microsof t Corp. v. i4i Ltd. P’ship","cite":"564 U.S. 91","y":2011,"id":"2010/10-290","sc":1,"by":{"3":"28"},"q":[{"src":"brief","b":3,"text":"only where a competing interpretation gives effect ‘to every clause and word of a statute.’","cite":"564 U.S. 91, 106"}]},{"t":"case","label":"OPM v. Richmond","cite":"496 U.S. 414","y":1990,"id":"1989/88-1943","sc":1,"by":{"3":"15, 20, 41","4":"5, 19","6":"13"},"q":[{"src":"brief","b":3,"text":"‘no money can be paid out of the Treasury unless it has been appropriated by an act of Congress.’","cite":"496 U.S. 414, 424"},{"src":"brief","b":3,"text":"From [this Court’s] earliest cases, [it] ha[s] recognized that equitable estoppel will not lie against the Government as it lies against private litigants.","cite":"496 U.S. at 419"},{"src":"argument","who":"Mr. Kneedler","text":"This Court has described it as a straightforward and explicit command in OPM versus Richmond. That command is a central feature of the separation of powers under the Constitution, and it's reinforced by the requirement that appropriations bills originate in the House of Representatives, which was designed to ensure that the representatives of the people would have and would jealously guard the power of the purse."}]},{"t":"case","label":"Prairie County v. United States","cite":"782 F.3d 685","y":2015,"url":"https://www.courtlistener.com/c/F.3d/782/685/","by":{"3":"28, 37","6":"13"}},{"t":"case","label":"Radzanower v. Touche Ross & Co.","cite":"426 U.S. 148","y":1976,"id":"1975/75-268","sc":1,"by":{"3":"26","6":"14"}},{"t":"case","label":"Ricci v. DeStefano","cite":"557 U.S. 557","y":2009,"id":"2008/07-1428","sc":1,"by":{"3":"26"}},{"t":"case","label":"Society for the Propagation of the Gospel v. Wheeler","cite":"22 F. Cas. 756","y":1814,"court":"C.C.D.N.H.","url":"https://www.courtlistener.com/c/F.%20Cas./22/756/","by":{"3":"52"}},{"t":"case","label":"Springdale Convalescent Ctr. v. Mathews","cite":"545 F.2d 943","y":1977,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/545/943/","by":{"3":"31"}},{"t":"case","label":"United States v. Navajo Nation","cite":"556 U.S. 287","y":2009,"id":"2008/07-1410","sc":1,"by":{"3":"15, 19, 29, 30","4":"22","5":"19","6":"19, 20"},"q":[{"src":"brief","b":3,"text":"‘mandat[es] compensation for damages sustained as a result of a breach of th[ose] duties.’","cite":"556 U.S. 287, 290-291"},{"src":"brief","b":3,"text":"two hurdles that must be cleared.","cite":"556 U.S. 287, 290"},{"src":"brief","b":5,"text":"‘mandat[es] compensation for damages sustained as a result of a breach.’","cite":"556 U.S. 287, 290-91"},{"src":"brief","b":6,"text":"can fairly be interpreted as mandating compensation for damages sustained as a result of a breach of the duties.","cite":"556 U.S. 287, 291"},{"src":"brief","b":6,"text":"need not explicitly provide that the right or duty it creates is enforceable through a suit for damages","cite":"556 U.S. at 290"}]},{"t":"case","label":"Usery v. Turner Elkhorn Mining Co.","cite":"428 U.S. 1","y":1976,"id":"1975/74-1302","sc":1,"by":{"3":"52"}},{"t":"case","label":"Wisconsin & Michigan Ry. Co. v. Powers","cite":"191 U.S. 379","y":1903,"id":"scdb/1903-030","sc":1,"by":{"3":"54","5":"10"}},{"t":"const","label":"Amendment V","clauses":[["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"3":"12"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","by":{"3":"32","4":"20"}},{"t":"usc","label":"31 U.S.C. § 1350","url":"https://www.law.cornell.edu/uscode/text/31/1350","by":{"3":"9"}},{"t":"law","label":"Pub. L. No. 113-76","url":"https://www.govinfo.gov/link/plaw/113/public/76","by":{"3":"8, 9"}},{"t":"law","label":"Pub. L. No. 114-223","url":"https://www.govinfo.gov/link/plaw/114/public/223","by":{"3":"10"}},{"t":"law","label":"Pub. L. No. 95-480","url":"https://www.govinfo.gov/link/statute/92/1576","by":{"3":"31"}},{"t":"usc","label":"16 U.S.C. § 1531","url":"https://www.law.cornell.edu/uscode/text/16/1531","by":{"3":"51"}},{"t":"law","label":"Pub. L. No. 114-254","url":"https://www.govinfo.gov/link/plaw/114/public/254","by":{"3":"10"}},{"t":"usc","label":"28 U.S.C. § 1505","url":"https://www.law.cornell.edu/uscode/text/28/1505","by":{"3":"19"}},{"t":"usc","label":"28 U.S.C. § 1346","url":"https://www.law.cornell.edu/uscode/text/28/1346","subs":["(a)(2)"],"by":{"3":"19"}},{"t":"usc","label":"42 U.S.C. § 1395w-101","url":"https://www.law.cornell.edu/uscode/text/42/1395w-101","by":{"3":"31"}},{"t":"usc","label":"42 U.S.C. § 1396","url":"https://www.law.cornell.edu/uscode/text/42/1396","subs":["(1976)"],"by":{"3":"31"}},{"t":"usc","label":"42 U.S.C. § 1396b","url":"https://www.law.cornell.edu/uscode/text/42/1396b","subs":["(a)(1988)","(a)"],"by":{"3":"31, 32"}},{"t":"usc","label":"42 U.S.C. § 18001","url":"https://www.law.cornell.edu/uscode/text/42/18001","subs":["(g)(1)"],"by":{"3":"3, 5"}},{"t":"usc","label":"42 U.S.C. § 1396a","url":"https://www.law.cornell.edu/uscode/text/42/1396a","by":{"3":"22","4":"15"}},{"t":"usc","label":"42 U.S.C. § 18021","url":"https://www.law.cornell.edu/uscode/text/42/18021","subs":["(a)(1)(B)"],"by":{"3":"5"}},{"t":"usc","label":"42 U.S.C. § 18041","url":"https://www.law.cornell.edu/uscode/text/42/18041","by":{"3":"6"}},{"t":"usc","label":"42 U.S.C. § 18043","url":"https://www.law.cornell.edu/uscode/text/42/18043","subs":["(c)"],"by":{"3":"6, 8, 15, 23"}},{"t":"usc","label":"2 U.S.C. § 622","url":"https://www.law.cornell.edu/uscode/text/2/622","subs":["(2)(A)(i)","(2)(A)(ii)","(9)"],"stext":{"head":"§622. Definitions","paras":[[0,"For purposes of this Act—"],[1,"(1) The terms \"budget outlays\" and \"outlays\" mean, with respect to any fiscal year, expenditures and net lending of funds under budget authority during such year."],[1,"(2) Budget authority and new budget authority.—"],[2,"(A) In general.—The term \"budget authority\" means the authority provided by Federal law to incur financial obligations, as follows:"],[3,"(i) provisions of law that make funds available for obligation and expenditure (other than borrowing authority), including the authority to obligate and expend the proceeds of offsetting receipts and collections;"],[3,"(ii) borrowing authority, which means authority granted to a Federal entity to borrow and obligate and expend the borrowed funds, including through the issuance of promissory notes or other monetary credits;"],[3,"(iii) contract authority, which means the making of funds available for obligation but not for expenditure; and"],[3,"(iv) offsetting receipts and collections as negative budget authority, and the reduction thereof as positive budget authority."],[2,"(B) Limitations on budget authority.—With respect to the Federal Hospital Insurance Trust Fund, the Supplementary Medical Insurance Trust Fund, the Unemployment Trust Fund, and the railroad retirement account, any amount that is precluded from obligation in a fiscal year by a provision of law (such as a limitation or a benefit formula) shall not be budget authority in that year."],[2,"(C) New budget authority.—The term \"new budget authority\" means, with respect to a fiscal year—"],[3,"(i) budget authority that first becomes available for obligation in that year, including budget authority that becomes available in that year s 1 a result of a reappropriation; or"],[3,"(ii) a change in any account in the availability of unobligated balances of budget authority carried over from a prior year, resulting from a provision of law first effective in that year;"],[2,"and includes a change in the estimated level of new budget authority provided in indefinite amounts by existing law."],[1,"(3) The term \"tax expenditures\" means those revenue losses attributable to provisions of the Federal tax laws which allow a special exclusion, exemption, or deduction from gross income or which provide a special credit, a preferential rate of tax, or a deferral of tax liability; and the term \"tax expenditures budget\" means an enumeration of such tax expenditures."],[1,"(4) The term \"concurrent resolution on the budget\" means—"],[2,"(A) a concurrent resolution setting forth the congressional budget for the United States Government for a fiscal year as provided in section 632 of this title; and"],[2,"(B) any other concurrent resolution revising the congressional budget for the United States Government for a fiscal year as described in section 635 of this title."],[1,"(5) The term \"appropriation Act\" means an Act referred to in section 105 of title 1."],[1,"(6) The term \"deficit\" means, with respect to a fiscal year, the amount by which outlays exceeds 2 receipts during that year."],[1,"(7) The term \"surplus\" means, with respect to a fiscal year, the amount by which receipts exceeds 2 outlays during that year."],[1,"(8) The term \"government-sponsored enterprise\" means a corporate entity created by a law of the United States that—"],[2,"(A)(i) has a Federal charter authorized by law;"],[2,"(ii) is privately owned, as evidenced by capital stock owned by private entities or individuals;"],[2,"(iii) is under the direction of a board of directors, a majority of which is elected by private owners;"],[2,"(iv) is a financial institution with power to—"],[3,"(I) make loans or loan guarantees for limited purposes such as to provide credit for specific borrowers or one sector; and"],[3,"(II) raise funds by borrowing (which does not carry the full faith and credit of the Federal Government) or to guarantee the debt of others in unlimited amounts; and"],[2,"(B)(i) does not exercise powers that are reserved to the Government as sovereign (such as the power to tax or to regulate interstate commerce);"],[2,"(ii) does not have the power to commit the Government financially (but it may be a recipient of a loan guarantee commitment made by the Government); and"],[2,"(iii) has employees whose salaries and expenses are paid by the enterprise and are not Federal employees subject to title 5."],[1,"(9) The term \"entitlement authority\" means—"],[2,"(A) the authority to make payments (including loans and grants), the budget authority for which is not provided for in advance by appropriation Acts, to any person or government if, under the provisions of the law containing that authority, the United States is obligated to make such payments to persons or governments who meet the requirements established by that law; and"],[2,"(B) the food stamp program."],[1,"(10) The term \"credit authority\" means authority to incur direct loan obligations or to incur primary loan guarantee commitments."],[1,"(11) The terms \"emergency\" and \"unanticipated\" have the meanings given to such terms in section 900(c) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/2/622?type=usc&year=mostrecent&link-type=html"},"by":{"3":"21, 21, 21","6":"10"},"q":[{"src":"brief","b":3,"text":"provisions of law that make funds available for obligation and expenditure.","cite":"2 U.S.C. 622(2)(A)(i)"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"provided by Federal law to incur fnancial obligations,","cite":"2 U. S. C. § 622(2)(A)"}]},{"t":"usc","label":"25 U.S.C. § 450j-1","url":"https://www.law.cornell.edu/uscode/text/25/450j-1","subs":["(b)(2012)"],"by":{"3":"37"}},{"t":"usc","label":"31 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/31/701","subs":["(2)"],"by":{"3":"15, 21, 25, 28, 56"}},{"t":"usc","label":"31 U.S.C. § 1301","url":"https://www.law.cornell.edu/uscode/text/31/1301","subs":["(d)"],"by":{"3":"15, 21, 25, 28, 56"},"q":[{"src":"brief","b":3,"text":"A law may be construed to make an appropriation out of the Treasury * * * only if the law specifically states that an appropriation is made.","cite":"31 U.S.C. 1301(d)"},{"src":"brief","b":3,"text":"A law may be construed * * * to authorize making a contract for the payment of money in excess of an appropriation only if the law specifically states that * * * such a contract may be made.","cite":"31 U.S.C. 1301(d)"}]},{"t":"usc","label":"42 U.S.C. § 300gg-93","url":"https://www.law.cornell.edu/uscode/text/42/300gg-93","subs":["(e)"],"by":{"3":"7"}},{"t":"usc","label":"42 U.S.C. § 1395w-112","url":"https://www.law.cornell.edu/uscode/text/42/1395w-112","subs":["(b)"],"by":{"4":"14"}},{"t":"case","label":"Fed. Express Corp. v. Holowecki","cite":"552 U.S. 389","y":2008,"id":"2007/06-1322","sc":1,"by":{"5":"11"}},{"t":"case","label":"Loughrin v. United States","cite":"573 U.S. 351","y":2014,"id":"2013/13-316","sc":1,"by":{"5":"17"}},{"t":"case","label":"Me. Cmty. Health Options v. United States","cite":"133 Fed. Cl. 1","y":2017,"url":"https://www.courtlistener.com/c/Fed.%20Cl./133/1/","by":{"5":"11"}},{"t":"case","label":"Community Health Choice, Inc. v. United States","cite":"141 Fed.Cl. 744","y":2019,"url":"https://www.courtlistener.com/c/Fed.Cl./141/744/","by":{"6":"18"}},{"t":"case","label":"Conway v. United States","cite":"2019 WL 4877280","y":2019,"court":"Fed.Cl. Oct. 3","by":{"6":"19"},"q":[{"src":"brief","b":6,"text":"can fairly be interpreted as mandating compensation.","cite":"2019 WL 4877280"}]},{"t":"case","label":"Dougherty v. United States","cite":"18 Ct.Cl. 496","y":1883,"url":"https://www.courtlistener.com/c/Ct.Cl./18/496/","by":{"6":"12"}},{"t":"case","label":"Farmer v. United States","cite":"2018 WL 1365797","y":2018,"court":"D.S.C. Mar. 16","by":{"6":"18"}},{"t":"case","label":"Ferris v. United States","cite":"27 Ct.Cl. 542","y":1892,"url":"https://www.courtlistener.com/c/Ct.Cl./27/542/","by":{"6":"12, 24"}},{"t":"case","label":"Fry v. Centers for Medicare and Medicaid Services","cite":"2019 WL 3801822","y":2019,"court":"N.D. Ill. Aug. 13","by":{"6":"18, 21"},"q":[{"src":"brief","b":6,"text":"the Court of Federal Claims has authority to provide an adequate remedy","cite":"2019 WL 3801822"}]},{"t":"case","label":"Gerhart v. United States Dep’t of Health & Human Servs.","cite":"242 F. Supp. 3d 806","y":2017,"court":"S.D. Iowa","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/242/806/","by":{"6":"18"}},{"t":"case","label":"Glidden Co. v. Zdanok","cite":"370 U.S. 530","y":1962,"id":"1961/242","sc":1,"by":{"6":"11"}},{"t":"case","label":"Lebron v. Nat’l R.R. Passenger Corp.","cite":"513 U.S. 374","y":1995,"id":"1994/93-1525","sc":1,"by":{"6":"25"},"q":[{"src":"brief","b":6,"text":"for the Government and those who do business with it.","cite":"513 U.S. 374, 379, 380 n.1"}]},{"t":"case","label":"Lovett v. United States","cite":"104 Ct.Cl. 557","y":1945,"url":"https://www.courtlistener.com/c/Ct.Cl./104/557/","by":{"6":"11"}},{"t":"case","label":"New York Central R.R. Co. v. United States","cite":"65 Ct.Cl. 115","y":1928,"url":"https://www.courtlistener.com/c/Ct.Cl./65/115/","by":{"6":"11"}},{"t":"case","label":"Pennsylvania Dept. of Corrections v. Yeskey","cite":"524 U.S. 206","y":1998,"id":"1997/97-634","sc":1,"by":{"6":"20"}},{"t":"case","label":"Peralta v. Heights Medical Center, Inc.","cite":"485 U.S. 80","y":1988,"id":"1987/86-1430","sc":1,"by":{"6":"18"}},{"t":"case","label":"R.A.V. v. City of St. Paul","cite":"505 U.S. 377","y":1992,"id":"1991/90-7675","sc":1,"by":{"6":"26"}},{"t":"case","label":"Republic Nat’l Bank of Miami v. United States","cite":"506 U.S. 80","y":1992,"id":"1992/91-767","sc":1,"by":{"6":"12"}},{"t":"case","label":"Richardson v. United States Dep’t of Health & Human Servs.","cite":"2018 WL 1569772","y":2018,"court":"D. Nev. Mar. 30","by":{"6":"18"}},{"t":"case","label":"Train v. City of New York","cite":"420 U.S. 35","y":1975,"id":"1974/73-1377","sc":1,"by":{"6":"10, 20"}},{"t":"case","label":"U.S. House of Representatives v. Burwell","cite":"2015 WL 9316243","y":2015,"court":"D.D.C. Dec. 2","by":{"6":"2"},"q":[{"src":"argument","who":"Mr. Kneedler","text":"That command is a central feature of the separation of powers under the Constitution, and it's reinforced by the requirement that appropriations bills originate in the House of Representatives, which was designed to ensure that the representatives of the people would have and would jealously guard the power of the purse."},{"src":"argument","who":"Justice Breyer","text":"What policy, constitutional or otherwise, would be served by a rule that says a GS-12 can make the United States pay the money, but the Congress of the United States, House and Senate, signed by the President, cannot --"}]},{"t":"case","label":"United States v. Emery, Bird, Thayer Realty Co.","cite":"237 U.S. 28","y":1915,"id":"scdb/1914-056","sc":1,"by":{"6":"4"}},{"t":"case","label":"United States v. White Mountain Apache Tribe","cite":"537 U.S. 465","y":2003,"id":"2002/01-1067","sc":1,"by":{"6":"20"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"right capable of grounding a claim within the waiver of sovereign immunity if, but only if, it `can fairly be interpreted as mandating compensation by the Federal Government for the damage sustained.'","cite":"537 U. S. 465, 472"},{"src":"argument","who":"Mr. Clement","text":"And I think compared to cases of this Court, like White Mountain Apache and the Mitchell case from 1983, it's sometimes called Mitchell II, this case is a very straightforward case of saying that a money-mandating statute is enforceable in the Court of Claims under the Tucker Act."},{"src":"argument","who":"Mr. Clement","text":"And I think that's a very difficult proposition to sustain if you take seriously not just 100 years of Court of Claims and Federal Circuit cases but also compare it to White Mountain Apache, compare it to -- compare it to the Mitchell case from 1983."},{"src":"argument","who":"Mr. Clement","text":"I think White Mountain Apache, I think Mitchell, the 1983 Mitchell decision, sometimes referred to as Mitchell II, are cases where this Court said there's money mandating directly from a statute."}]},{"t":"usc","label":"5 U.S.C. § 5942","url":"https://www.law.cornell.edu/uscode/text/5/5942","by":{"6":"20"}},{"t":"usc","label":"37 U.S.C. § 204","url":"https://www.law.cornell.edu/uscode/text/37/204","by":{"6":"20"}},{"t":"reg","label":"42 C.F.R. § 422.458","url":"https://www.ecfr.gov/current/title-42/section-422.458","by":{"6":"8, 4"}},{"t":"reg","label":"67 Fed. Reg. 41,070","url":"https://www.govinfo.gov/link/fr/67/41070","by":{"6":"8"}},{"t":"reg","label":"77 Fed. Reg. 17,236","url":"https://www.govinfo.gov/link/fr/77/17236","by":{"6":"7"}},{"t":"reg","label":"78 Fed. Reg. 15,412","url":"https://www.govinfo.gov/link/fr/78/15412","by":{"6":"7"}},{"t":"usc","label":"42 U.S.C. § 1395w","url":"https://www.law.cornell.edu/uscode/text/42/1395w","by":{"6":"4"}}]};